'use client'
import axios from 'axios'
import React, { useEffect } from 'react'

function getCurrentUser() {
useEffect(()=>{
    const fetchUser = async ()=>{
        try {
            const result = await axios.get("/api/currentUser")
            console.log(result.data)
        } catch (error) {
            console.log(error)
        }

    }
    fetchUser()
},[])
}

export default getCurrentUser
